/* GetGlobex language switcher memory + suggestion banner. Generated by tools/build_i18n.py.
   Never redirects (crawlers and users always get the URL they asked for). At most it shows a dismissible banner
   that links to the equivalent page listed in this page's own language switcher. */
(function () {
  var S = {"en": {"label": "Language", "msg": "This page is also available in English.", "go": "Switch to English", "dismiss": "Dismiss"}, "vi": {"label": "Ngôn ngữ", "msg": "Trang này cũng có bằng Tiếng Việt.", "go": "Chuyển sang Tiếng Việt", "dismiss": "Đóng"}, "es-MX": {"label": "Idioma", "msg": "Esta página también está disponible en Español (México).", "go": "Cambiar a Español (México)", "dismiss": "Cerrar"}};
  var KEY = 'gg-lang', DKEY = 'gg-lang-dismissed';
  function get(k) { try { return window.localStorage.getItem(k); } catch (e) { return null; } }
  function set(k, v) { try { window.localStorage.setItem(k, v); } catch (e) {} }
  document.addEventListener('click', function (e) {
    var a = e.target && e.target.closest ? e.target.closest('a[data-lang]') : null;
    if (a) set(KEY, a.getAttribute('data-lang'));
  });
  var links = {};
  document.querySelectorAll('.lang-switch--footer a[data-lang]').forEach(function (a) { links[a.getAttribute('data-lang')] = a.getAttribute('href'); });
  var cur = document.documentElement.getAttribute('lang') || 'en';
  var pref = get(KEY);
  // browser-language hints only apply on the EN default pages; on vi/es pages only an explicit stored choice counts
  if (!pref && cur === 'en') {
    var nl = navigator.languages || [navigator.language || ''];
    for (var i = 0; i < nl.length && !pref; i++) {
      var c = String(nl[i]).toLowerCase();
      if (c.indexOf('vi') === 0) pref = 'vi'; else if (c.indexOf('es') === 0) pref = 'es-MX'; else if (c.indexOf('en') === 0) pref = 'en';
    }
  }
  if (!pref || pref === cur || !links[pref] || !S[pref] || get(DKEY) === pref) return;
  var t = S[pref];
  var b = document.createElement('div');
  b.className = 'lang-suggest'; b.setAttribute('role', 'region'); b.setAttribute('aria-label', t.label); b.setAttribute('lang', pref);
  var p = document.createElement('p'); p.textContent = t.msg + ' ';
  var a = document.createElement('a'); a.href = links[pref]; a.textContent = t.go; a.setAttribute('data-lang', pref); a.setAttribute('hreflang', pref);
  p.appendChild(a);
  var x = document.createElement('button'); x.type = 'button'; x.textContent = t.dismiss;
  x.addEventListener('click', function () { set(DKEY, pref); b.parentNode && b.parentNode.removeChild(b); });
  b.appendChild(p); b.appendChild(x);
  document.body.appendChild(b);
})();
